use std::sync::LazyLock;

use regex::bytes::Regex;

use crate::declare_rule;
use crate::lint::context::SourceContext;
use crate::lint::diagnostic::{Diagnostic, Location};
use crate::lint::file_tree::EntryKind;
use crate::lint::rule::{Severity, SourceRule};

pub struct SourceContainsPrebuiltYappParser;

declare_rule! {
    /// A Patched `.pm` file is a Parse::Yapp parser generated by `yapp`: its
    /// text has the header `# This file was generated using Parse::Yapp
    /// version N`, which the tarball should not carry since the grammar is
    /// the source. Reported at pedantic severity with an empty extra and the
    /// path as the Location, the pointer form lintian's
    /// `languages/perl/yapp` Check emits.
    ///
    /// Only `.pm` names are read (case-sensitive, as lintian reads them).
    /// Hardlinks are read as files; quilt `.pc/` is skipped. Unlike the
    /// `files/source-missing` Rules, `debian/missing-sources/` is not skipped.
    SourceContainsPrebuiltYappParser,
    code = "LN1630",
    tag = "source-contains-prebuilt-yapp-parser",
    default_selected = false,
    experimental = false,
}

static YAPP_HEADER: LazyLock<Regex> = LazyLock::new(|| {
    Regex::new(r"(?m)^#\s+This file was generated using Parse::Yapp version [\d.]+")
        .expect("valid regex")
});

impl SourceRule for SourceContainsPrebuiltYappParser {
    fn run(&self, ctx: &mut SourceContext<'_>) {
        let Some(files) = ctx.files() else {
            return;
        };
        let candidates: Vec<_> = files
            .query()
            .kinds([EntryKind::RegularFile, EntryKind::Hardlink])
            .into_iter()
            .filter(|entry| !entry.path().starts_with(".pc"))
            .filter(|entry| entry.path().to_string_lossy().ends_with(".pm"))
            .collect();
        let flagged: Vec<_> = candidates
            .into_iter()
            .filter(|entry| {
                files
                    .read(entry)
                    .is_ok_and(|bytes| YAPP_HEADER.is_match(&bytes))
            })
            .map(|entry| entry.path().to_path_buf())
            .collect();
        for path in flagged {
            ctx.diagnostic(
                Diagnostic::warn("")
                    .with_severity(Severity::Pedantic)
                    .with_location(Location {
                        path,
                        line: None,
                        column: None,
                    }),
            );
        }
    }
}

#[cfg(test)]
mod tests {
    use crate::lint::tester::{SourcePackageCase, SourcePackageTester, SourceTreeTester, TestFile};

    use super::*;

    const CONTROL: &str = "Source: example\n\
         Maintainer: Example <ex@example.com>\n\
         Standards-Version: 4.7.2\n\
         \n\
         Package: example\n\
         Architecture: all\n\
         Description: example\n extra\n";

    const PARSER: &str =
        "#\n# This file was generated using Parse::Yapp version 1.21.\n#\npackage Dot;\n";

    #[test]
    fn test() {
        let pass = vec![
            vec![("debian/control", TestFile::from(CONTROL))],
            vec![
                ("debian/control", TestFile::from(CONTROL)),
                // The grammar is the source, not this header.
                ("perl/Dot.yp", TestFile::new(PARSER)),
                // The header without a version is not Yapp's.
                (
                    "perl/Hand.pm",
                    TestFile::new("# This file was generated using Parse::Yapp\n"),
                ),
                // Only `.pm` names are read.
                ("perl/Dot.PM", TestFile::new(PARSER)),
                // Quilt's `.pc/` is not the packaging's file.
                (".pc/perl/Dot.pm", TestFile::new(PARSER)),
            ],
        ];
        let fail = vec![
            vec![
                ("debian/control", TestFile::from(CONTROL)),
                ("perl/Dot.pm", TestFile::new(PARSER)),
            ],
            // The header counts wherever it is in the file.
            vec![
                ("debian/control", TestFile::from(CONTROL)),
                (
                    "lib/Late.pm",
                    TestFile::new(format!("package Late;\n{PARSER}")),
                ),
            ],
            // A hardlink is a file too.
            vec![
                ("debian/control", TestFile::from(CONTROL)),
                ("perl/Dot.pm", TestFile::new(PARSER).hardlink()),
            ],
            // Not skipped in `debian/missing-sources/`.
            vec![
                ("debian/control", TestFile::from(CONTROL)),
                ("debian/missing-sources/perl/Dot.pm", TestFile::new(PARSER)),
            ],
        ];
        SourceTreeTester::new(SourceContainsPrebuiltYappParser, pass, fail).test_and_snapshot();
    }

    #[test]
    fn test_source_package() {
        let pass = vec![SourcePackageCase::from(vec![(
            "debian/control",
            TestFile::from(CONTROL),
        )])];
        let fail = vec![SourcePackageCase::from(vec![
            ("debian/control", TestFile::from(CONTROL)),
            ("perl/Dot.pm", TestFile::new(PARSER)),
        ])];
        SourcePackageTester::new(SourceContainsPrebuiltYappParser, pass, fail).test_and_snapshot();
    }
}
